```cpp
#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^#\s*([0-9]+)\s*([a-zA-Z0-9_]+)");
    std::smatch match;
    while (std::regex_search(html, match, re)) {
        html = html.replace(match.position(), match.length(), "<h" + match[1] + ">" + match[2] + "</h" + match[1] + ">");
    }
    return html;
}
```

This function uses a regular expression to match markdown headings (e.g., `#1 Heading`) and replaces them with corresponding HTML tags (e.g., `<h1>Heading</h1>`). The regular expression `^#\s*([0-9]+)\s*([a-zA-Z0-9_]+)` matches lines starting with `#` followed by zero or more whitespace characters, a number, and then a heading text. The `std::regex_search` function finds all matches and replaces them with the corresponding HTML tags.

